function applySettings(){const kits=['Red Stars','Green Stars','Golden Stars','Blue Stars'];const colors=[0xc05336,0x397e62,0xd3ab45,0x447e9b];$('#kit-name').textContent=kits[colors.indexOf(settings.color)];document.documentElement.style.setProperty('--red','#'+settings.color.toString(16));$('#sound-button').setAttribute('aria-pressed',String(settings.sound));$('#sound-button').setAttribute('aria-label',settings.sound?'Turn sound off':'Turn sound on');soundscape.setEnabled(settings.sound);for(const channel of ['music','ambience','effects']){soundscape.setVolume(channel,settings[channel]);$('#'+channel+'-volume').value=String(Math.round(settings[channel]*100));$('#'+channel+'-level').textContent=Math.round(settings[channel]*100)+'%';}$('#launch-sound').setAttribute('aria-pressed',String(settings.sound));$('#launch-sound').setAttribute('aria-label',settings.sound?'Turn sound off':'Turn sound on');updateLaunchMusic();$('#sound-button').textContent=$('#launch-sound').textContent=settings.sound?'♫':'♪';$('#sound-setting').checked=settings.sound;$('#opponent-setting').value=settings.opponent;$('#difficulty-setting').value=settings.difficulty;$('#quality-setting').value=settings.quality;$('#auto-sprint-setting').checked=settings.autoSprint;$('#left-actions-setting').checked=settings.leftActions;document.body.classList.toggle('left-actions',settings.leftActions);if(world&&world.quality!==settings.quality){world.setQuality(settings.quality);}try{localStorage.setItem('gsg.3d.settings',JSON.stringify(settings));}catch{}}
