function rules(g=selectedGame){$('#rules-select').value=g.id;const el=$('#rules-body');el.innerHTML='';const heading=document.createElement('h3');heading.textContent=g.name;const outdoors=document.createElement('p');outdoors.textContent=g.desc+(g.aliases?' Also known as: '+g.aliases+'.':'');const ruleList=document.createElement('ul');g.rules.forEach(r=>{const li=document.createElement('li');li.textContent=r;ruleList.append(li);});const digital=document.createElement('h3');digital.textContent='This 3D arcade version';const instructions=document.createElement('p');instructions.textContent=g.instructions;const limits=document.createElement('p');limits.className='small-copy';limits.textContent=g.id==='dame'?'Declared variation: captures are compulsory, players may choose a capture path, kings fly, men capture backwards, captured pieces remain until the chain finishes, kings are crowned at turn end, and 80 non-capturing moves draw. A player reduced to one piece loses.':g.id==='ludo'?'Declared house rules: two sides (CPU or local opponent), safe start squares, no capture bonus, no three-sixes penalty, friendly stacking allowed.':g.note||'Local rules vary. This arcade interpretation is not a claim of one national ruleset.';el.append(heading,outdoors,ruleList,digital,instructions,limits);const sourceHeading=document.createElement('h3');sourceHeading.textContent='Research sources';el.append(sourceHeading);g.refs.forEach(id=>{const source=sources[id];if(!source)return;const a=document.createElement('a');a.href=source.url;a.target='_blank';a.rel='noopener';a.textContent=source.name+' ↗';el.append(a);});const note=document.createElement('p');note.className='small-copy';note.textContent='Independent Three.js implementation inspired by Four Corners GH. Licensed character, material and audio credits are linked from the lobby. Research checked 31 October 2026.';el.append(note);}
