async function toggleFullscreen(){
 const root=document.documentElement;
 try{if(document.fullscreenElement||document.webkitFullscreenElement)await (document.exitFullscreen?.()||document.webkitExitFullscreen?.());
 else if(root.requestFullscreen)await root.requestFullscreen();else if(root.webkitRequestFullscreen)root.webkitRequestFullscreen();else document.body.classList.toggle('full-window');}
 catch{document.body.classList.toggle('full-window');}
 requestAnimationFrame(()=>{world?.resize();active?.frameView?.();requestAnimationFrame(updatePlayInsets);});
}
