window.addEventListener('keydown',e=>{if(state==='lobby'&&!document.querySelector('dialog[open]')&&!['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)&&['ArrowLeft','ArrowRight','PageUp','PageDown'].includes(e.key)){const button=$(['ArrowLeft','PageUp'].includes(e.key)?'#previous-page':'#next-page');if(!button.disabled){e.preventDefault();button.click();}return;}if(e.key==='Escape'&&state==='playing'){e.preventDefault();if(viewOptions.open){viewOptions.open=false;viewOptions.querySelector('summary').focus();}else pause();return;}if(state!=='playing'||document.querySelector('dialog[open]')||e.target.closest?.('button,summary,input,select,textarea,[contenteditable="true"]'))return;const key=e.key.toLowerCase();if(key==='c'&&!e.repeat&&active?.cycleCamera){active.cycleCamera();return;}if(['arrowup','arrowdown','arrowleft','arrowright','w','a','s','d','shift',' '].includes(key))e.preventDefault();keys.add(key);if(['arrowup','arrowdown','arrowleft','arrowright','w','a','s','d'].includes(key))input.target=null;if(key==='shift')input.sprint=true;if(!e.repeat){const action=active?.actions.find(a=>!a.disabled&&(a.key.toLowerCase()===key||a.key==='Space'&&key===' '));if(action&&!action.hold){if(action.charge)active.hold?.(action.id);else act(action.id);}}});window.addEventListener('keyup',e=>{const key=e.key.toLowerCase(),wasPressed=keys.delete(key);if(state==='playing'&&wasPressed){const a=active?.actions.find(a=>a.charge&&(a.key.toLowerCase()===key||a.key==='Space'&&key===' '));if(a)act(a.id);}if(e.key==='Shift')input.sprint=false;});window.addEventListener('blur',()=>{clearInput();if(state==='playing')pause();});document.addEventListener('visibilitychange',()=>{soundscape.setVisible(!document.hidden);if(document.hidden)$('#replay-video').pause();clearInput();if(document.hidden&&state==='playing')pause();last=performance.now();});window.addEventListener('resize',()=>{if(state==='playing')clearInput();world?.resize();active?.frameView?.();requestAnimationFrame(updatePlayInsets);if(state==='lobby')renderMenu();});
