let scenePointer=null;
canvas.addEventListener('pointerdown',e=>{if(state!=='playing')return;canvas.focus({preventScroll:true});if(active.drag){if(scenePointer)return;scenePointer={id:e.pointerId,x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY,moved:false};canvas.setPointerCapture(e.pointerId);}else active.hit(world.pick(e.clientX,e.clientY,e.pointerType==='touch'?24:0));});
canvas.addEventListener('pointermove',e=>{if(!scenePointer||scenePointer.id!==e.pointerId)return;const dx=e.clientX-scenePointer.x,dy=e.clientY-scenePointer.y;if(Math.hypot(e.clientX-scenePointer.startX,e.clientY-scenePointer.startY)>5)scenePointer.moved=true;if(scenePointer.moved)active?.drag?.(dx,dy);scenePointer.x=e.clientX;scenePointer.y=e.clientY;});
