const stick=$('#joystick');
function stickMove(e){const r=stick.getBoundingClientRect(),max=r.width*.32;
 const v=joystickVector(e.clientX-r.left-r.width/2,e.clientY-r.top-r.height/2,max);
 input.stick={x:v.x,z:v.z};input.stickSprint=v.sprint;input.target=null;
 $('#stick-knob').style.transform=`translate(${v.x*max}px,${v.z*max}px)`;refreshSprint();
}
joystick=bindJoystick(stick,{move:stickMove,reset(){input.stick={x:0,z:0};input.stickSprint=false;$('#stick-knob').style.transform='';refreshSprint();}});
