async function generatePreviews(missing=null){world.thumbnail=true;world.renderer.setSize(640,400,false);world.camera.aspect=640/400;world.camera.fov=52;world.camera.updateProjectionMatrix();const requested=new URLSearchParams(location.search).get('generate-previews'),games=missing|| (requested?catalogue.filter(g=>requested.split(',').includes(g.id)):catalogue);for(let i=0;i<games.length;i++){const g=games[i];$('#loading-text').textContent=`Preparing ${g.name} preview… ${i+1}/${games.length}`;const m=createMode({world,input:idleInput,ui:quietUI,game:g,settings});for(const a of m.actors)animateActor(a,0,0,a.userData.pose||'idle',0);if(['pampanaa','shooting','pilolo'].includes(g.id))world.setCamera([-13,8,15,-4,.7,-1],true);if(g.id==='football'){const p=m.teams[0][m.selected].position;world.setCamera([p.x-5,3.2,p.z+1,p.x+10,1,p.z],true);m.b.position.set(p.x+.6,.12,p.z);}if(g.id==='fourcorners')world.setCamera([0,20,23,0,0,0],true);world.render(0,0);thumbs.set(g.id,canvas.toDataURL('image/jpeg',.88));m.dispose();if(i%4===0)await new Promise(requestAnimationFrame);}world.thumbnail=false;}
let worldLoading=null,slowFrames=0,loadProgress=null;
function ensureWorld(progress=()=>{}){
 loadProgress=progress;
 if(world)return Promise.resolve(world);
 return worldLoading??=(async()=>{
  loadProgress?.('Loading the game engine…');await loadEngine();
  const quality=touchDevice?(settings.quality==='low'?'low':'balanced'):settings.quality;
  const tasks=[loadAthletes((done,total)=>loadProgress?.(`Loading players ${done} / ${total}…`),touchDevice?'low':quality),loadSurfaces(quality),loadFootballAssets()];
  let deadline;await Promise.race([Promise.allSettled(tasks),new Promise(resolve=>{deadline=setTimeout(resolve,12000);})]);clearTimeout(deadline);
  loadProgress?.('Preparing your playground…');
  world=new World(canvas,settings.quality);applySettings();world.resize();
  if(settings.quality==='high')world.loadSky().catch(()=>{});
  return world;
 })().catch(error=>{worldLoading=null;throw error;});
}
function boot(){
 for(const g of catalogue)thumbs.set(g.id,'assets/previews/'+g.id+'.jpg?v=418');
 applySettings();$('#loading').hidden=true;lobby();if(settings.sound)soundscape.unlock().then(updateLaunchMusic).catch(()=>{});
 const params=new URLSearchParams(location.search);if(params.has('game'))openSetup(gameById(params.get('game')));
 else{$('#lobby').hidden=true;$('#launch-screen').hidden=false;document.body.classList.add('in-launch');}
 wakeFrame();
}
function frame(now){
 animationFrame=null;
 if(document.hidden||!world||state!=='playing')return;
 if(world.quality!=='high'&&now-last<1000/30-1){animationFrame=requestAnimationFrame(frame);return;}
 const interval=now-last,dt=Math.min(.05,Math.max(0,interval/1000));last=now;elapsed+=dt;
 if(world.quality!=='low'){slowFrames=interval>48&&interval<250?slowFrames+1:Math.max(0,slowFrames-1);if(slowFrames>90){world.setQuality('low');ui.note('Lighter graphics enabled for smoother play.');slowFrames=0;}}
 const started=performance.now(),steps=Math.max(1,Math.ceil(dt/(1/60)));refreshSprint();
 // Physics stays at 60 Hz; skeletons and hand IK update once per displayed frame.
 world.deferAnimation=true;
 try{for(let i=0;i<steps&&state==='playing';i++)active?.tick(dt/steps,elapsed-dt+(i+1)*dt/steps);}
 finally{world.deferAnimation=false;}
 if(actionCharge){const power=active?.online||!actionCharge.hasPower?Math.min(1,(now-actionCharge.startedAt)/1100):actionCharge.power;$('#action-buttons').style.setProperty('--action-power',(power*100)+'%');}
 active?.animate?.(elapsed);world.render(dt,elapsed);
 if(world.quality==='low'){const scale=renderBudget.sample(performance.now()-started,interval,world.resolutionScale||1);if(scale!==(world.resolutionScale||1)){world.resolutionScale=scale;world.resize();}}
 if(state==='playing')animationFrame=requestAnimationFrame(frame);
}
document.querySelectorAll('[data-replay]').forEach(b=>{b.disabled=!replay.supported();b.onclick=async()=>{const url=await replay.finish();if(!url)return;$('#replay-video').src=url;$('#save-replay').href=url;$('#save-replay').download='ghana-street-games-replay.'+replay.extension();soundscape.setScene('replay');$('#replay-dialog').showModal();$('#replay-video').play().catch(()=>{});};});$('#replay-dialog').addEventListener('close',()=>{$('#replay-video').pause();soundscape.setScene(state==='lobby'?'menu':state==='playing'?'game':state,active?.venue?.kind||'pitch');});
boot();

